int DashZone_ProcessAutoRun(WarpAutoRun *self, float x, float y, float z, float yaw) {
    WarpDashMgr *mgr;
    float angle;
    float diff;
    float step;
    mgr = WarpDashMgr_GetInstance(self->mgrId);
    if (mgr == 0 || self->timer <= 0.0f || self->zone == -1) {
        self->vel.x = 0.0f;
        self->vel.y = 0.0f;
        self->vel.z = 0.0f;
        if (self->state == 1) {
            self->state = 2;
        } else {
            self->state = 0;
        }
        return self->state;
    }
    self->timer -= 0.016666668f;
    WarpZone_GetOBBSpeed(mgr, self->zone, &self->yaw);
    self->yawTarget = self->yaw;
    angle = yaw;
    if (angle > 0.0f) {
        while (angle >= 360.0f) {
            angle -= 360.0f;
        }
    } else if (angle < 0.0f) {
        while (angle < 0.0f) {
            angle += 360.0f;
        }
    }
    diff = self->yaw - angle;
    if (diff > 180.0f) {
        diff -= 360.0f;
    } else if (diff < -180.0f) {
        diff += 360.0f;
    }
    if (diff > 0.0f) {
        step = (float)__fabs(diff) * 0.05f;
        angle += step;
        if (self->yaw < angle) {
            angle = self->yaw;
        }
    } else {
        step = (float)__fabs(diff) * 0.05f;
        angle -= step;
        if (self->yaw > angle) {
            angle = self->yaw;
        }
    }
    self->yaw = angle;
    return 1;
}

